import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BqDA2HS7.js";const s="/RefractRouter/strategy-stage.svg",i="/RefractRouter/screenshots/dsh-20261014/strategy-stage-settings.png",f=JSON.parse('{"title":"Stage · 阶段","description":"","frontmatter":{},"headers":[],"relativePath":"strategies/stage.md","filePath":"strategies/stage.md"}'),d={name:"strategies/stage.md"};function n(l,e,c,g,h,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="stage-·-阶段" tabindex="-1">Stage · 阶段 <a class="header-anchor" href="#stage-·-阶段" aria-label="Permalink to &quot;Stage · 阶段&quot;">​</a></h1><p>Stage 从高效模型开始，根据新增的可信执行证据选择下一轮模型。 它调整模型调用，不规划 DAG，也不替接入方执行工具。</p><figure class="doc-diagram"><img src="'+s+'" alt="Stage 的优先级判定：未确认停止、重复失败升级、规则信号比较"><figcaption>判定顺序固定：先查未确认，再查重复失败，最后算规则信号；保持期结束后恢复高效模型。</figcaption></figure><h2 id="规则模式" tabindex="-1">规则模式 <a class="header-anchor" href="#规则模式" aria-label="Permalink to &quot;规则模式&quot;">​</a></h2><p>默认窗口为最近 3 条有效工具结果，判断阈值为 0.5，接管保持 2 次执行。 “两次”包含触发切换的当前调用和下一次调用。</p><ol><li>工具结果或模型用量未确认，停止后续受管调用。</li><li>出现新的同类可信重复失败，切换到指定强执行角色。</li><li>保持期内继续使用该角色。</li><li>有新证据时计算规则信号；保持结束且无新困难时恢复高效角色。</li><li>没有有效信号时使用高效角色；旧事件不重复触发。</li></ol><p>单次合理测试失败、正常搜索、权限拒绝和基础设施故障不等于模型能力不足。 失败指纹必须关联工具、规范化参数和可信失败信息，不能仅比较错误码。</p><h2 id="规则与-jev-如何协作" tabindex="-1">规则与 Jev 如何协作 <a class="header-anchor" href="#规则与-jev-如何协作" aria-label="Permalink to &quot;规则与 Jev 如何协作&quot;">​</a></h2><p>可选协作模式在受控边界询问本地结构化 Judge 或官方 Jev。 规则处理工具事实、去重、安全和保持；Judge 提供有限回答信号，Python 决定最终动作。 它不会为每条模糊文字无限增加判别链条。</p><p>协作参数包括判别间隔、每任务判别批次上限、保持和降回确认次数。 该模式保留实验标识；超时或后端崩溃停止，不自动切换云端或重发。</p><h2 id="必要设置" tabindex="-1">必要设置 <a class="header-anchor" href="#必要设置" aria-label="Permalink to &quot;必要设置&quot;">​</a></h2><p>高效、强执行模型与各自推理等级；规则参数；协作模式另选择 Judge、数据域及期限。 两个角色绑定相同模型与参数时可按准入运行，但不会产生实际模型切换。</p><h2 id="系统设置示范" tabindex="-1">系统设置示范 <a class="header-anchor" href="#系统设置示范" aria-label="Permalink to &quot;系统设置示范&quot;">​</a></h2><p>打开 <strong>规划路由 → 正在编辑的策略：Stage</strong>，先指定两个角色，再核对轨迹判断方式。</p><figure class="doc-screenshot compact"><a href="/screenshots/dsh-20261014/strategy-stage-settings.png" target="_blank" rel="noopener"><img src="'+i+'" alt="实际 Stage 设置：DeepSeek Flash 高效角色、Kimi K3 强执行角色、规则判断、保持 2 次"></a><figcaption>2026-10-14 实际界面：规则模式不调用额外 Judge；保持 2 次包含触发接管的当前执行。</figcaption></figure><p>截图高效角色为 <code>ark/deepseek-v4-flash</code>、强执行角色为 <code>ark/kimi-k3</code>，均为 High。 “强执行”是用户指定的接管角色，名称本身不证明该模型更适合当前任务。 展开 Stage 高级参数可核对窗口与阈值；只有选择规则与 Judge 的协作方式，才需要额外后端。</p><p>适用场景是持续调试：Agent 先读代码、跑测试；若新增可信证据表明同一问题反复失败， 下一轮临时使用强执行器。保持结束后若没有新困难，恢复高效角色。一次预期中的测试失败 或审批拒绝不会直接触发升级；重复失败分支由确定性夹具验证，不能把下面的正常续接案例 写成真实发生了升级。</p><h2 id="工具证据的来源" tabindex="-1">工具证据的来源 <a class="header-anchor" href="#工具证据的来源" aria-label="Permalink to &quot;工具证据的来源&quot;">​</a></h2><p>DSH 原生事件能携带结构化工具结果。纯 Base URL 的普通文本结果往往没有可信退出状态， 会记为 <code>unclassified</code>。Codex CLI 的可选证据适配另见<a href="./../integrations/codex.html">接入说明</a>。 Router 不从正文“成功／失败”猜测退出状态。</p><h2 id="轨迹应该看到什么" tabindex="-1">轨迹应该看到什么 <a class="header-anchor" href="#轨迹应该看到什么" aria-label="Permalink to &quot;轨迹应该看到什么&quot;">​</a></h2><p>证据 ID、评分、重复失败／保持／恢复原因、保持前后计数、实际模型、推理等级与费用。 规则模式应没有额外 Judge 调用；协作模式记录实际 Judge 批次、原始答案和实验状态。</p><h3 id="真实案例" tabindex="-1">真实案例 <a class="header-anchor" href="#真实案例" aria-label="Permalink to &quot;真实案例&quot;">​</a></h3><p>stage-01 任务：第一轮无有效工具信号（<code>no-signal</code>），使用高效模型 <code>deepseek-v4-flash</code>； 用户要求只执行一次 <code>printf %s STAGE_01_OK</code>，读取 stdout 后只回复 <code>STAGE_01_OK</code>。 宿主完成一次原生工具调用后，回执判定为 <code>ambiguous</code>，保持同一模型继续执行。 共 2 次受管调用，费用 1.254 AFP，首字 1.24 秒，总延迟 4.38 秒，含 1 次原生工具调用。 同批次 24 项 Stage 任务全部成功，每项恰好一次宿主工具调用。 这是<a href="./../planning.html#六策略真实运行案例">2026-09-29 冻结验收</a>，两次执行都用同一个模型。</p>',23)])])}const _=a(d,[["render",n]]);export{f as __pageData,_ as default};
